}

.tm-input {
  background: rgba(255, 255, 255, 0.9) !important;
  border: 1px solid var(--abyss-line) !important;
  color: var(--abyss-text) !important;
  font-family: Georgia, serif !important;
  font-size: 13px !important;
  padding: 8px 12px !important;
}

.tm-input::placeholder {
  color: #a78b97 !important;
  font-style: italic !important;
}

.tm-send-btn {
  background: var(--abyss-red) !important;
  color: #fff !important;
  border-radius: 0 !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
}

/* ==================================================
   建议面板（增强磨砂）
   ================================================== */
.tm-suggestions-panel {
  background: rgba(255, 255, 255, 0.85) !important;
  backdrop-filter: blur(15px) !important;
  -webkit-backdrop-filter: blur(15px) !important;
  border: 1px solid var(--abyss-line) !important;
  border-radius: 0 !important;
}

.tm-suggestion-item {
  border-bottom: 1px dashed var(--abyss-line) !important;
  padding: 10px 16px !important;
}

.tm-suggestion-direction {
  color: var(--abyss-red) !important;
  font-size: 9px !important;
  letter-spacing: 0.1em !important;
  text-transform: uppercase !important;
}

.tm-suggestion-text {
  color: var(--abyss-text) !important;
  font-size: 15px !important;
